            if (!adj.containsKey(node)) {
                continue;
            }
            for (List<Integer> edge : adj.get(node)) {
                answer = Math.min(answer, edge.get(1));
                if (!visit[edge.get(0)]) {
                    visit[edge.get(0)] = true;
                    q.offer(edge.get(0));
                }
            }
        }
        return answer;
    }

